int get_data_block_for_inode(struct inode *inode, sector_t iblock,
                             struct buffer_head *bh, int create, int flag,
                             pgoff_t *next_pgofs) {
    int ret;
    struct address_space *mapping = inode->i_mapping;
    struct buffer_head *mapped_bh = NULL;
    sector_t phys_block;

    ret = map_blocks(mapping, iblock, &phys_block, create, flag, next_pgofs);
    if (ret < 0)
        return ret;

    if (!phys_block)
        return -ENXIO;

    mapped_bh = sb_bread(inode->i_sb, phys_block);
    if (!mapped_bh)
        return -EIO;

    if (bh) {
        *bh = *mapped_bh;
        bh->b_bdev = inode->i_sb->s_bdev;
    }

    brelse(mapped_bh);
    return 0;
}

int retrieve_inode_block(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    struct address_space *mapping = inode->i_mapping;
    int ret;

    ret = block_map(mapping, iblock, create, flag, bh, next_pgofs);
    if (ret < 0)
        return ret;

    if (!buffer_mapped(bh))
        return -EIO;

    return 0;
}

int retrieve_inode_block(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    int ret;
    struct address_space *mapping = inode->i_mapping;
    struct page *page;

    ret = mapping->a_ops->bmap(mapping, iblock);
    if (ret <= 0)
        return ret;

    page = grab_cache_page(mapping, iblock);
    if (!page)
        return -ENOMEM;

    lock_buffer(bh);
    bh->b_bdev = inode->i_sb->s_bdev;
    bh->b_blocknr = ret;
    bh->b_state = 0;
    bh->b_size = 1 << inode->i_blkbits;
    bh->b_private = page;
    bh->b_end_io = NULL;
    unlock_buffer(bh);

    if (next_pgofs)
        *next_pgofs = iblock + 1;

    return 0;
}

int retrieve_inode_block(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    struct address_space *mapping = inode->i_mapping;
    int ret;

    ret = block_map(mapping, iblock, create, flag, bh, next_pgofs);
    if (ret < 0)
        return ret;

    if (!bh)
        return -EIO;

    return 0;
}

int get_data_block(struct inode *inode, sector_t iblock, struct buffer_head *bh, int create, int flag, pgoff_t *next_pgofs) {
    struct address_space *mapping = inode->i_mapping;
    struct page *page;
    int ret;

    page = read_mapping_page(mapping, iblock, NULL);
    if (IS_ERR(page)) {
        return PTR_ERR(page);
    }

    ret = block_map(inode, iblock, create, flag, &bh);
    if (ret < 0) {
        return ret;
    }

    if (!bh) {
        return -EINVAL;
    }

    bh->b_page = page;
    bh->b_blocknr = iblock;
    *next_pgofs = iblock + 1;

    return 0;
}
